script.text:

			&ScriptFlowGridSelect;

function load$&Identity;Grid$(g) {
	var f = g.get_element().parentForm;
	if (g._rowCount > 0) g._focusWhenTabChanged();
		else try {$get(String.format('{0}_updateDlgCancel', f._id)).focus();} catch (ex) {}
	try {$get('FlowGridTagId').parentNode.title = '';} catch (ex) {}
	g.add_onRender(onRender$&Identity;Grid$);
	g.add_onResponseComplete(on$&Identity;Grid$ResponseComplete);

}
function scatter$&Identity;Grid$(g) {g._memvars = [];}
function close$&Identity;Grid$(g){
	try{g.remove_onRender(onRender$&Identity;Grid$);} catch(ex){}
	try {g.remove_onResponseComplete(on$&Identity;Grid$ResponseComplete);} catch (ex) {}

}
function onRender$&Identity;Grid$(g){ 
	g.request(g,'GetData','GetData',[],['ma_kh', 'tk', 'ngay_ct0', 'ngay_ct2', 'ma_dvcs', 'ma_nt']);
}
function on$&Identity;Grid$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		case 'GetData':
			var l1 = g._getColumnOrder('ngay_ct');
			console.log(result);
			for(var i = 0 i < result.length; i++){
				g._appendRow(null,true);
				var row = g._rowCount;
				var o = g._getItem(row,	l1);
				o.focus();
				g.setItemGridBehavior(o, [
					['ngay_ct', result[i][1], null, null],
					['so_ct', result[i][2], '', null],
					['stt_rec', result[i][3], '', null],
					['chon', false, null, null],
					['t_so_luong', result[i][4], null, null],
					['t_tt_nt', result[i][5], null, null]
				]);
			}
			break;
	}
}
